func (uf *UserFacade) UpdateUser(request UpdateUserRequest, userSession UserSession) (UserView, error) {
    user := userSession.User
    if request.Bio != nil {
        user.Bio = *request.Bio
    }
    if request.Image != nil {
        user.Image = *request.Image
    }
    if request.Password != nil {
        user.EncodedPassword = uf.passwordService.EncodePassword(*request.Password)
    }
    if request.Username != nil {
        uf.UpdateUsername(user, *request.Username)
    }
    if request.Email != nil {
        uf.UpdateEmail(user, *request.Email)
    }
    savedUser, err := uf.userRepository.Save(user)
    if err != nil {
        return UserView{}, err
    }
    return savedUser.ToUserView(userSession.Token), nil
}

