func (u *UserFacade) Follow(username string, futureFollower User) (ProfileView, error) {
    userToFollow, err := u.userRepository.FindByUsernameOrFail(username)
    if err != nil {
        return ProfileView{}, err
    }
    futureFollower.Follow(userToFollow)
    if err := u.userRepository.Save(futureFollower); err != nil {
        return ProfileView{}, err
    }
    return userToFollow.ToFollowedProfileView(), nil
}

